// Client-side filtering for the question tables generated by hooks/questions.py.
document.addEventListener("DOMContentLoaded", () => {
  document.querySelectorAll(".question-filter").forEach((filterBox) => {
    const table = filterBox.nextElementSibling;
    if (!table || table.tagName !== "TABLE") return;
    const counter = table.nextElementSibling;
    const rows = Array.from(table.querySelectorAll("tbody tr"));
    const controls = filterBox.querySelectorAll("[data-filter]");

    const apply = () => {
      const f = {};
      controls.forEach((c) => (f[c.dataset.filter] = c.value.trim().toLowerCase()));
      let shown = 0;
      rows.forEach((row) => {
        const ok =
          (!f.level || row.dataset.level === f.level) &&
          (!f.difficulty || row.dataset.difficulty === f.difficulty) &&
          (!f.tag || row.dataset.tags.split(" ").includes(f.tag)) &&
          (!f.text || row.textContent.toLowerCase().includes(f.text));
        row.hidden = !ok;
        if (ok) shown++;
      });
      if (counter) counter.textContent = `מוצגות ${shown} מתוך ${rows.length} שאלות`;
    };

    controls.forEach((c) => c.addEventListener("input", apply));
    apply();
  });
});
